draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw tomato
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 10*Math.sin(t), 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2 - 50, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 30);
  ctx.lineTo(W/2 - 100, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 10);
  ctx.lineTo(W/2 - 80, H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 10);
  ctx.lineTo(W/2 - 120, H/2 + 20);
  ctx.stroke();

  // draw text
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Tomato: technically a fruit', W/2, H/2 + 80);
  ctx.fillText('Rich in lycopene', W/2, H/2 + 110);

  ctx.restore();
}
